import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office — quote", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("plain sword, newcomer → premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet, newcomer → premium 71 G (60 + 6 + 5)");
  it.todo("plain staff, newcomer → premium 93 G (80 + 8 + 5)");
  it.todo("plain potion, newcomer → premium 49 G (40 + 4 + 5)");
  it.todo("2 runes → 50 G base premium → premium 60 G");
  it.todo("3 runes → 60 G base premium (block) → premium 71 G");
  it.todo("4 runes → 100 G base premium (no block) → premium 115 G");
  it.todo("7 runes → 175 G base premium → 197.5 G rounded up to premium 198 G");
  it.todo("2 runes + 1 moonstone → 75 G base premium (different types, no block) → premium 88 G");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two blocks) → premium 137 G");
  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge → premium 115 G");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge → premium 145 G");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges → premium 195 G");
  it.todo("cursed sword + plain amulet → curse surcharge only on sword base (210 G) → premium 231 G");
  it.todo("customer with exactly 2 years → loyalty discount applies → plain sword premium 95 G");
  it.todo("customer with 1 year → no loyalty discount → plain sword premium 115 G");
  it.todo("second quote in scenario → 15 % follow-up discount, first insurance still applies → plain sword premium 100 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 → premium 160 G");
  it.todo("quote with an unknown item type (broomstick) → rejected with an error");
});

describe("Claim Office — claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 → payout 400, remainingCap 1600");
  it.todo("rune damage 200 → payout 100, remainingCap 400");
  it.todo("schema example: amulet damage 200 → payout 100, remainingCap 1100");
  it.todo("dragon-material sword enchantment 8, damage 1000 → payout 400");
  it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 → payout 700");
  it.todo("steel sword enchantment 9, damage 1000 → payout 400");
  it.todo("payout of 350.5 G is rounded down to 350 G (enchantment 9, damage 901)");
  it.todo("sword (500) + amulet (300) damaged in one event → deductible per item → payout 600, remainingCap 2600");
  it.todo("two swords insured, both damaged 500 → each its own deductible → payout 800, remainingCap 3200");
  it.todo("cursed sword cap is based on insurance value 1000 → damage 500 → remainingCap 1600");
  it.todo("sword + 3 runes → insurance sum 1750, cap 3500 → sword damage 500 → remainingCap 3100");
  it.todo("two successive 1500 G claims on a sword → payouts 1400 then 600, remainingCap 600 then 0");
  it.todo("more damage entries of a type than insured items → claim rejected");
  it.todo("damage to an item not in the policy → claim rejected");
  it.todo("damage to an unknown item type → claim rejected");
  it.todo("damage with negative amount → claim rejected");
});

describe("claim-office CLI", () => {
  it.todo("reads a scenario from stdin and writes results JSON to stdout");
  it.todo("exits non-zero with an error on stderr and no results on stdout for invalid input");
});

