type Item = { type: string };
type Scenario = { steps: { items: Item[] }[] };

export const runScenario = (scenario: Scenario): unknown => {
  const items = scenario.steps[0].items;
  const basePremium = items.length * 100;
  const firstInsurance = basePremium * 0.1;
  return { results: [{ premium: basePremium + firstInsurance + 5 }] };
};
EOF
