export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: "quote"; items: Item[] }[];
};
export type ScenarioResult = { results: { premium: number }[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const isRuneBlock = (items: Item[]): boolean =>
  items.filter((item) => item.type === "rune").length === BLOCK_SIZE;

const basePremiumOf = (items: Item[]): number =>
  isRuneBlock(items) ? RUNE_BLOCK_PREMIUM : sumOfBasePremiums(items);

const quotePremium = (items: Item[]): number => {
  const basePremium = basePremiumOf(items);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: [{ premium: quotePremium(scenario.steps[0].items) }],
});

